def button(text, action='', style='white', href=''):
    attr = f'href="{E(href)}"' if href else f'type="button" data-request="{E(action,quote=True)}"'
    tag='a' if href else 'button'
    return f'<{tag} class="btn btn-{style}" {attr}>{E(text)} {icons["arrow"]}</{tag}>'

